        "qZaBb2z6mE2zLL2u": {
          "name": "Criar objeto",
          "description": "Frequência três vezes ao dia\nEfeito O duende produz um item de seu chapéu, de trás de sua jaqueta, de dentro de um buraco no toco de uma árvore ou de qualquer outro local inesperado. Este item conjurado não deve ter mais que 1 volume e deve ser feito de material relativamente comum (como tecido, madeira, pedra ou mesmo metal de baixo valor, como ferro ou chumbo). Ele não pode depender de arte intrincada ou peças móveis complexas, nunca cumpre um Custo ou algo semelhante e não pode ser feito de materiais preciosos ou materiais com raridade incomum ou superior. O objeto criado é temporário e dura 1 hora ou até que o duende crie um novo item, o que ocorrer primeiro."
        },
