          "name": "Manto em Brasas",
          "description": "Gatilho Um aliado adjacente é alvo de um efeito que causa dano de fogo\nEfeito A raposa brasa cobre seu aliado, concedendo ao aliado resistência ao fogo 10 contra o ataque recebido.\nEfeito: Manto em Brasas"
