    "version": 1,
    "status": "MACHINE_DRAFT",
    "fields": {
      "name": "Texugo Gigante",
      "description": "O violento e territorial texugo gigante é um predador implacável. Carnívoro obrigatório, pode consumir presas que variam de coelhos a veados, gado e até mesmo aventureiros ocasionais. As garras de um texugo gigante são afiadas e fortes o suficiente para cavar túneis em rocha sólida. Eles normalmente têm 4 pés (1,2 metros) alto na altura dos ombros e pesam 500 libras.\nOs texugos gigantes são extremamente territoriais e são conhecidos por defenderem suas tocas com fúria, mesmo que a criatura não seja necessariamente ameaçadora. Essas tocas tendem a ser maiores do que um texugo gigante normalmente precisa, o que às vezes chama a atenção de outras criaturas em busca de um lar. Isto leva a muitos encontros entre texugos gigantes e animais maiores, como os ursos.",
      "size": "Médio",
      "senses": {
        "low-light-vision": "visão na penumbra",
        "scent-imprecise-30": "faro impreciso 30 pés (9 metros)"
      },
      "languages": {},
      "defenses": {
        "immunities": [],
        "resistances": [],
        "weaknesses": []
      },
      "attacks": {
        "N5U9pyyTitN5UDgN": {
          "name": "Maxilas",
          "damage": "1d8+4 perfurante"
        },
        "lVmzxYHnjQBBZTN4": {
          "name": "Garra",
          "damage": "1d6+4 cortante"
        }
      },
      "actions": {
        "RUPrm8gIOS2f852a": {
          "name": "Ferocidade",
          "description": ""
        },
        "iSVPM2m77YXV78mJ": {
          "name": "Fúria do Texugo",
          "description": "O texugo gigante entra em um estado de pura raiva que dura 1 minuto, até que não haja mais inimigos que ele possa perceber, ou até cair Inconsciente, o que ocorrer primeiro.\nEnquanto estiver em fúria, o texugo gigante tem CA 17, seu Golpe de mandíbula causa 1d8+8 de dano e seu Golpe de garra causa 1d6+6 de dano. Enquanto estiver em fúria, o texugo gigante também não pode usar ações que tenham a característica concentração, exceto Procurar.\nDepois de parar de se enfurecer, um texugo gigante não poderá usar Badger Rage novamente por 1 minuto.\nEfeito: Raiva"
        }
      },
      "spellcasting": {}
    }
