      "name": "Trovão Vivo",
      "description": "Um trovão vivo é uma pequena nuvem de tempestade (às vezes na forma vaga de um humanóide) que estala e explode com trovões.\nAlguns elementais incorporam aspectos do ar, como fumaça, relâmpagos e neblina.",
