        "DmKxrzqQZ1NdAQHI": {
          "name": "Absorver Força",
          "description": "Frequência uma vez por rodada\nGatilho Uma barragem de força ou Dardo de Força (veja abaixo) é disparado contra o bruxo, e o bruxo está ciente disso e tem a mão livre\nEfeito O feiticeiro \"captura\" um projétil de força, absorvendo-o, evitando o dano e fazendo com que a mão brilhe enquanto segura essa energia. Uma mão que contém energia não pode ser usada para nenhum outro propósito, exceto para usar Force Dart. A energia dura 1 minuto ou até ser liberada."
        },
        "wBOmt44hbAvJFvdg": {
          "name": "Forçar dardo",
          "description": "1 a 3\nO bruxo-feiticeiro dispara um dardo de força por ação gasta (causando (1d4+1)[força] de dano cada). Eles não podem gastar mais ações nesta habilidade do que possuem mãos livres. Se eles usarem uma mão que tenha Força Absorvida, essa mão lançará dois dardos em vez de um, gastando a energia retida."
        },
